package com.phobos.emulator.ui.carts

import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

/**
 * Compares [LookResolver] with Cartridge's own answers for hand-written cases (fixture generated by
 * tools/cart-fixtures/make-fixtures.mjs from the verbatim pipeline copy).
 */
class LookResolverTest {

    private fun resource(name: String) = javaClass.getResource("/carts/$name")!!.readText()

    private val fixture = JSONObject(resource("look-fixtures.json"))

    @Test
    fun shellFinishesMatchCartridge() {
        val expected = fixture.getJSONArray("shellFinishes")
        assertEquals(expected.length(), LookResolver.shellFinishes.size)
        for (i in 0 until expected.length()) {
            val o = expected.getJSONObject(i)
            assertEquals(o.getString("id"), LookResolver.shellFinishes[i].id)
            assertEquals(o.getString("label"), LookResolver.shellFinishes[i].label)
        }
    }

    @Test
    fun shellColorsMatchCartridge() {
        val expected = fixture.getJSONArray("shellColors")
        assertEquals(expected.length(), LookResolver.shellColors.size)
        for (i in 0 until expected.length()) {
            val o = expected.getJSONObject(i)
            assertEquals(o.getString("name"), LookResolver.shellColors[i].name)
            assertEquals(o.getString("hex"), LookResolver.shellColors[i].hex)
        }
    }

    @Test
    fun defaultColorsMatchCartridge() {
        val expected = fixture.getJSONObject("defaultShellColors")
        assertEquals(expected.length(), LookResolver.defaultShellColors.size)
        for (key in expected.keys()) {
            assertEquals(expected.getString(key), LookResolver.defaultShellColors[key])
        }
    }

    @Test
    fun lookCasesMatchCartridge() {
        val cases = fixture.getJSONArray("looks")
        for (i in 0 until cases.length()) {
            val c = cases.getJSONObject(i)
            val cartLooks = c.getJSONObject("cartLooks")
            val looks = buildMap {
                for (key in cartLooks.keys()) {
                    val o = cartLooks.getJSONObject(key)
                    put(key, LookResolver.Look(o.getString("finish"), o.getString("color")))
                }
            }
            val game = LookResolver.GameInput(c.optLong("id", 1L), c.getString("file"))
            val actual = LookResolver.resolve(game, c.getString("system"), looks, c.getBoolean("specialCarts"))
            val expected = if (c.isNull("expectedLook")) null else c.getJSONObject("expectedLook")
            if (expected == null) {
                assertNull("case $i: ${c.getString("file")}", actual)
            } else {
                assertEquals("case $i finish: ${c.getString("file")}", expected.getString("finish"), actual?.finish)
                assertEquals("case $i color: ${c.getString("file")}", expected.getString("color"), actual?.color)
                assertEquals("case $i special: ${c.getString("file")}", expected.getBoolean("special"), actual?.special)
            }
        }
    }

    @Test
    fun wearCasesMatchCartridge() {
        val cases = fixture.getJSONArray("wears")
        for (i in 0 until cases.length()) {
            val c = cases.getJSONObject(i)
            assertEquals(
                "case $i wear ${c.getString("wear")} at ${c.getLong("playtime")}",
                c.getInt("expected"),
                LookResolver.wearLevel(c.getLong("playtime"), c.getString("wear")),
            )
        }
    }

    @Test
    fun specialEditionsMatchThroughTheDisplayNamesTheUiUses() {
        val pairs = listOf(
            "Famicom" to "nes", "Super Famicom" to "snes", "Game Boy" to "gb",
            "Game Boy Color" to "gbc", "Game Boy Advance" to "gba", "Nintendo 64" to "n64",
            "Mega Drive" to "genesis",
        )
        val files = listOf(
            "Pokemon - Red Version (USA).zip",
            "Super Mario Bros. (World).nes",
            "The Legend of Zelda (USA).nes",
        )
        for ((display, id) in pairs) {
            assertEquals("mapping $display", id, CartShapes.entry(display)?.id)
            for (file in files) {
                assertEquals(
                    "$display/$file",
                    LookResolver.findSpecialEdition(file, id),
                    LookResolver.findSpecialEdition(file, display),
                )
            }
        }
        org.junit.Assert.assertNotNull(
            "a red Pokemon cart still matches through the display name",
            LookResolver.findSpecialEdition("Pokemon - Red Version (USA).zip", "Game Boy"),
        )
    }

    @Test
    fun resolveUsesTheDisplayKeysTheUiWrites() {
        val stored = mapOf("s:Game Boy" to LookResolver.Look("solid", "#123456"))
        val bySystem = LookResolver.resolve(
            LookResolver.GameInput(42, "No Special Name (USA).zip"),
            "Game Boy",
            stored,
            specialCarts = true,
        )
        assertEquals("s:<display> is the per-system key", LookResolver.Look("solid", "#123456"), bySystem)
        val special = LookResolver.resolve(
            LookResolver.GameInput(43, "Pokemon - Red Version (USA).zip"),
            "Game Boy",
            emptyMap(),
            specialCarts = true,
        )
        assertEquals("a special still resolves through resolve()", true, special?.special)
    }
}
